213		return ai.ProviderConfig{
214			ID:       provider.GetId(),
215			Title:    provider.GetTitle(),
216			Type:     convertAIProviderTypeFromStore(provider.GetType()),
217			Endpoint: provider.GetEndpoint(),
218			APIKey:   provider.GetApiKey(),
219		}
220	}
